<?php require '../config/auth.php';require_admin();require '../config/database.php';if(isset($_GET['id'],$_GET['status'])){$id=(int)$_GET['id'];$status=in_array($_GET['status'],['approved','rejected'],true)?$_GET['status']:'pending';$stmt=$conn->prepare("UPDATE claims SET status=? WHERE id=?");$stmt->bind_param("si",$status,$id);$stmt->execute();header('Location: claims.php');exit;}$res=$conn->query("SELECT claims.*,users.name,items.title FROM claims JOIN users ON users.id=claims.user_id JOIN items ON items.id=claims.item_id ORDER BY claims.created_at DESC");$basePath='../';$pageTitle='Manage Claims';include '../header.php';?><h2>Manage Claims</h2><table><tr><th>ID</th><th>Item</th><th>User</th><th>Message</th><th>Status</th><th>Action</th></tr><?php while($c=$res->fetch_assoc()):?><tr><td><?=(int)$c['id']?></td><td><?=htmlspecialchars($c['title'])?></td><td><?=htmlspecialchars($c['name'])?></td><td><?=htmlspecialchars($c['message'])?></td><td><?=htmlspecialchars($c['status'])?></td><td><a class="btn" href="?id=<?=(int)$c['id']?>&status=approved">Approve</a> <a class="btn danger" href="?id=<?=(int)$c['id']?>&status=rejected">Reject</a></td></tr><?php endwhile;?></table><?php include '../footer.php'; ?>